package cn.linkdeck.qa;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import cn.linkdeck.adb.*;import org.json.*;import java.io.*;import java.lang.reflect.*;
/** Public wizard, capability gating and frozen redacted export on Android. */
public class CompatibilityUiChecks extends AerialUiChecks {
 void rowTap(String label)throws Exception{Thread.sleep(1000);android.view.accessibility.AccessibilityNodeInfo root=appRoot();for(android.view.accessibility.AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(label)){if(!label.contentEquals(n.getText())||!n.isVisibleToUser())continue;android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);long down=SystemClock.uptimeMillis();for(int action:new int[]{android.view.MotionEvent.ACTION_DOWN,android.view.MotionEvent.ACTION_UP}){android.view.MotionEvent event=android.view.MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,r.exactCenterX(),r.exactCenterY(),0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(event,true);event.recycle();Thread.sleep(130);}return;}throw new AssertionError("Missing visible list row "+label);}
 void complete(String name,long after)throws Exception{awaitTask(name,after);idle();}
 public void onStart(){Bundle result=new Bundle();try{
  getTargetContext().getSharedPreferences("linkdeck",0).edit().putBoolean("resume_connection",false).putString("connect_mode","legacy").commit();activity=startActivitySync(new Intent().setClassName("cn.linkdeck.adb","cn.linkdeck.adb.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
  call("connectionWizard",new Class[]{});waitFor("wizard separates legacy, pairing and platform scope",()->dialogHas("传统 ADB")&&dialogHas("配对码无线调试")&&dialogHas("其他电视系统"));rowTap("其他电视系统 / 不确定");waitFor("non-Android platform is not promised APK management",()->dialogHas("Tizen")&&dialogHas("webOS")&&dialogHas("多设备内测版"));dialogTap("知道了");
  call("pairingForm",new Class[]{String.class,String.class},"","");waitFor("pairing form is visible without connecting",()->dialogHas("加密无线配对"));dialogTap("配对并连接");check(dialogHas("加密无线配对")&&!(Boolean)field("busy"),"missing pairing fields do not start a network job");dialogTap("取消");
  runOnMainSync(()->{try{((EditText)field("hostInput")).setText("127.0.0.1");((EditText)field("portInput")).setText("5555");}catch(Exception e){throw new RuntimeException(e);}});tap("连接设备");waitFor("legacy connection still works alongside new TLS support",()->client()!=null&&client().isConnected()&&!(Boolean)field("busy"));DeviceCapabilities.Snapshot actual=(DeviceCapabilities.Snapshot)field("capabilitySnapshot");check(actual!=null&&actual.sdk>0,"connection performs a fresh read-only snapshot");check(actual.items.get(DeviceCapabilities.DESKTOP).state==DeviceCapabilities.State.LIMITED,"generic connection never certifies desktop takeover");call("capabilityReport",new Class[]{});waitFor("report explains the limited meaning of checks",()->dialogHas("设备能力报告")&&dialogHas("基础检查通过不代表"));shot("v013-capabilities");dialogTap("关闭");
  DeviceCapabilities.Snapshot fixture=new DeviceCapabilities.Snapshot();fixture.user=0;fixture.model="PRIVATE_SERIAL 192.168.31.120";fixture.properties.put("ro.serialno","PRIVATE_SERIAL");fixture.sdk=22;fixture.items.get(DeviceCapabilities.SCREENSHOT).state=DeviceCapabilities.State.ABSENT;fixture.items.get(DeviceCapabilities.SCREENSHOT).reason="本地测试样例：截图命令缺失";set("capabilitySnapshot",fixture);set("capabilityClient",client());call("show",new Class[]{int.class},1);check(!find(activity.getWindow().getDecorView(),"截取设备屏幕").isEnabled(),"known missing screenshot interface disables its control");int count=((TaskJournal)field("journal")).snapshot().length();call("capture",new Class[]{});waitFor("blocked capability explains its reason",()->dialogHas("当前设备未提供此接口"));check(((TaskJournal)field("journal")).snapshot().length()==count,"blocked action does not enqueue a TV command");dialogTap("知道了");
  call("previewCompatibilityExport",new Class[]{DeviceCapabilities.Snapshot.class},fixture);waitFor("export preview explains local redaction",()->dialogHas("诊断报告导出预览")&&dialogHas("不会自动上传"));dialogTap("取消");File pending=new File(getTargetContext().getFilesDir(),"compatibility_pending.json");check(!pending.exists(),"cancel export creates no payload");String frozen=fixture.export();check(!frozen.contains("PRIVATE_SERIAL")&&!frozen.contains("192.168.31.120"),"report payload excludes serial and endpoint even in descriptive fields");call("writeDesktopFile",new Class[]{File.class,String.class},pending,frozen);
  set("capabilitySnapshot",actual);call("show",new Class[]{int.class},0);tap("断开连接");activity=startActivitySync(new Intent().setClassName("cn.linkdeck.adb","cn.linkdeck.adb.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));File destination=new File(getTargetContext().getCacheDir(),"compatibility-export-qa.json");long started=System.currentTimeMillis();call("onActivityResult",new Class[]{int.class,int.class,Intent.class},108,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(destination)));complete("导出兼容报告",started);check(read(destination).equals(frozen),"export survives activity replacement and disconnection without mixing reports");check(!pending.exists(),"successful export clears only the pending report");call("writeDesktopFile",new Class[]{File.class,String.class},pending,frozen);call("onActivityResult",new Class[]{int.class,int.class,Intent.class},108,Activity.RESULT_CANCELED,null);check(!pending.exists(),"cancelled system picker clears pending report");destination.delete();
  result.putString("stream","COMPATIBILITY NATIVE UI PASSED: "+passes+" checks.\n");finish(-1,result);
 }catch(Throwable e){try{shot("v013-compatibility-failure");}catch(Exception ignored){}result.putString("stream",android.util.Log.getStackTraceString(e));finish(0,result);}}
}
